import{_ as l,a0 as a,w as p,s as o,ao as u,I as s,x as e,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"在 KDE 中添加、切換、刪除和管理 Linux 用户 | LCTT x X-CMD","titleTemplate":false,"description":"在 KDE 中添加、切換、刪除和管理 Linux 用户 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 KDE 中添加、切換、刪除和管理 Linux 用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 KDE 中添加、切換、刪除和管理 Linux 用户 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220218 Add, switch, delete, and manage Linux users in KDE","title":"在 KDE 中添加、切換、刪除和管理 Linux 用户","tag":"202203","desc":""},"relativePath":"202203/20220218 Add, switch, delete, and manage Linux users in KDE.md","filePath":"[post].md"}'),d={name:"202203/20220218 Add, switch, delete, and manage Linux users in KDE.md"};function m(b,t,g,f,x,T){const r=a("Link");return p(),o("div",null,[t[25]||(t[25]=u('<h1 id="在-kde-中添加、切換、刪除和管理-linux-用户" tabindex="-1">在 KDE 中添加、切換、刪除和管理 Linux 用户 <a class="header-anchor" href="#在-kde-中添加、切換、刪除和管理-linux-用户" aria-label="Permalink to “在 KDE 中添加、切換、刪除和管理 Linux 用户”">​</a></h1><blockquote><p>在一台電腦上維護獨立的用户是一種奢侈，也是保護你自己和你關心的人的數據安全的一個好方法。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202203/03/104151iwevek3xzcr1113u.jpg" alt=""></p><p>在一個家庭中共享一台電腦通常是一件很隨意的事情。當你需要電腦時，你拿起它並開始使用它。這在理論上很簡單，而且大部分情況下是有效的。也就是説，直到你不小心拿起公用電腦，不小心把你的服務器的正常運行時間的截圖發到你伴侶的烹飪Blog上。然後，就到了建立獨立用户帳户的時候了。</p><p>從一開始，Linux 就是一個多用户系統。它的設計是把每個用户，只要他們登錄，都當作一個獨特的人，有一個屬於他們自己的桌面，一個獨特的網絡瀏覽器配置文件，訪問他們自己的文檔和文件，等等。KDE Plasma 桌面做了很多工作，使得從一個帳户切換到另一個帳户很容易，但首先你必須為每個你期望使用電腦的人設置一個用户帳户。你也可以為客人設置一個特殊的帳户（我稱這個帳户為 <code>guest</code>）。</p><h3 id="在-kde-中添加用户" tabindex="-1">在 KDE 中添加用户 <a class="header-anchor" href="#在-kde-中添加用户" aria-label="Permalink to “在 KDE 中添加用户”">​</a></h3>',6)),s("p",null,[t[1]||(t[1]=e("在 Linux 上有不同的方法來添加用户。一種方法是系統管理員式的 ",-1)),n(r,{href:"https://www.redhat.com/sysadmin/linux-commands-manage-users"},{default:i(()=>[...t[0]||(t[0]=[e("使用終端",-1)])]),_:1}),t[2]||(t[2]=e("。當你有很多用户需要添加時，這是非常有效的，所以你想把這個過程自動化或者只是減少鼠標點擊的次數。",-1))]),t[26]||(t[26]=u('<p>不過在 Plasma 桌面上，你可以用<ruby>用户<rt>Users</rt></ruby>程序來添加用户。<ruby>用户<rt>Users</rt></ruby>實際上是<ruby>系統設置<rt>System Settings</rt></ruby>中的一個控制面板，但你可以從你的應用菜單中啓動它，就像它是一個獨立的應用。</p><p><img src="https://opensource.com/sites/default/files/kde-users.jpg" alt="Users in KDE System Settings" title="Users in KDE System Settings"></p><p>要添加一個用户，點擊窗口底部的<ruby>添加新用户<rt>Add New User</rt></ruby>按鈕。</p><p><img src="https://opensource.com/sites/default/files/kde-users-add.jpg" alt="Adding a user in KDE" title="Adding a user in KDE"></p><p>給新用户一個<ruby>名字<rt>Name</rt></ruby>和一個<ruby>用户名<rt>Username</rt></ruby>。這些可能是相同的，但意圖是他們的名字是他們的姓名，而他們的用户名是他們用於使用的入口。例如，我的名字是 “Seth Kenlon”，而我的用户名是 <code>seth</code>。</p>',5)),s("p",null,[t[4]||(t[4]=e("將新用户指定為",-1)),t[5]||(t[5]=s("ruby",null,[e("標準用户"),s("rt",null,"Standard")],-1)),t[6]||(t[6]=e("或",-1)),t[7]||(t[7]=s("ruby",null,[e("管理員"),s("rt",null,"Administraor")],-1)),t[8]||(t[8]=e("。標準用户只對自己的環境有完全的控制權。他們可以 ",-1)),n(r,{href:"https://opensource.com/article/21/11/install-flatpak-linux"},{default:i(()=>[...t[3]||(t[3]=[e("安裝 Flatpak",-1)])]),_:1}),t[9]||(t[9]=e(" 並將數據保存到他們的主目錄，但他們不能影響機器上的其他用户。這是有用户帳户的好處之一。我不會認為我允許使用我的電腦的任何人打算刪除對我很重要的數據，但意外還是發生了。通過為我自己和我的伴侶創建一個單獨的用户帳户，我在保護我們每個人的數據，我也在保護我們每個人，避免意外地移動一個文件或誤放對另一個人很重要的數據。",-1))]),t[27]||(t[27]=u('<p>管理員可以進行全系統的更改。我通常在我的電腦上為自己保留這個角色，我也希望我的伴侶在她自己的電腦上為自己保留這個角色。然而，在工作中，這個角色屬於 IT 部門。</p><p>為用户創建一個<ruby>密碼<rt>Password</rt></ruby>，並重復<ruby>確認<rt>Confirm</rt></ruby>。登錄後，新用户可以改變他們的密碼。</p><p>要完成用户創建，請點擊<ruby>創建<rt>Create</rt></ruby>按鈕。</p><h3 id="切換用户" tabindex="-1">切換用户 <a class="header-anchor" href="#切換用户" aria-label="Permalink to “切換用户”">​</a></h3><p>在桌面有兩種不同的方式來切換用户。你可以註銷，然後讓另一個用户登錄，或者你可以從應用菜單的<ruby>電源/會話<rt>Power / Sessions</rt></ruby>子菜單中選擇<ruby>切換用户<rt>Switch user</rt></ruby>。</p><p><img src="https://opensource.com/sites/default/files/kde-users-switch.jpg" alt="Switching users in KDE" title="Switching users in KDE"></p><p>當一個新用户登錄時，你的當前桌面會被“凍結”或暫停，而另一個用户的新桌面會被調出來。你所有的窗口都保持打開。你甚至可以在遊戲中切換用户（如果你正在戰鬥中，你應該先暫停一下），當你切換回來時，你可以從你離開的地方繼續。更好的是，你的所有進程也會繼續運行。所以你可以在渲染視頻或編譯代碼時切換用户，當你切換回來時，你的視頻已經完成了渲染，或者你的代碼已經完成了編譯（只要有足夠的時間）。</p><p><img src="https://opensource.com/sites/default/files/kde-users-login.jpg" alt="Login" title="Login"></p><h3 id="刪除用户" tabindex="-1">刪除用户 <a class="header-anchor" href="#刪除用户" aria-label="Permalink to “刪除用户”">​</a></h3><p>當我有客人時，我經常在他們的逗留期間創建一個客人帳户，當他們離開後，我就刪除這個帳户。</p><p>你可以通過刪除一個用户的用户帳户來從你的電腦中刪除該用户。這將刪除他們的所有數據，所以要確保你要刪除的用户已經把他們需要的東西從機器上遷移掉了！</p><p><ruby>刪除用户<rt>Delete User</rt></ruby>按鈕位於<ruby>用户<rt>Users</rt></ruby>控制面板中的每個用户帳户下，也就是你最初創建用户的地方。</p><p><img src="https://opensource.com/sites/default/files/kde-users-delete.jpg" alt="Deleting a user" title="Deleting a user"></p><h3 id="linux-用户管理" tabindex="-1">Linux 用户管理 <a class="header-anchor" href="#linux-用户管理" aria-label="Permalink to “Linux 用户管理”">​</a></h3><p>在計算機上維護獨立的用户是一種奢侈，也是保護你自己的數據和你關心的人的數據安全的好方法。它允許每個用户都是獨一無二的，並使桌面成為他們自己的。在 Linux 中，這很容易，而且沒什麼影響，因此可以為朋友、房客和家人創建用户。</p><hr>',16)),s("p",null,[t[11]||(t[11]=e("via: ",-1)),n(r,{href:"https://opensource.com/article/22/2/manage-linux-users-kde"},{default:i(()=>[...t[10]||(t[10]=[e("https://opensource.com/article/22/2/manage-linux-users-kde",-1)])]),_:1})]),s("p",null,[t[16]||(t[16]=e("作者：",-1)),n(r,{href:"https://opensource.com/users/seth"},{default:i(()=>[...t[12]||(t[12]=[e("Seth Kenlon",-1)])]),_:1}),t[17]||(t[17]=e(" 選題：",-1)),n(r,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[13]||(t[13]=[e("lujun9972",-1)])]),_:1}),t[18]||(t[18]=e(" 譯者：",-1)),n(r,{href:"https://github.com/geekpi"},{default:i(()=>[...t[14]||(t[14]=[e("geekpi",-1)])]),_:1}),t[19]||(t[19]=e(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:i(()=>[...t[15]||(t[15]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[22]||(t[22]=e("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[20]||(t[20]=[e("LCTT",-1)])]),_:1}),t[23]||(t[23]=e(" 原創編譯，",-1)),n(r,{href:"https://linux.cn/"},{default:i(()=>[...t[21]||(t[21]=[e("Linux中國",-1)])]),_:1}),t[24]||(t[24]=e(" 榮譽推出",-1))])])}const k=l(d,[["render",m]]);export{L as __pageData,k as default};
